\begin{equation*}
    x^\tau(t) := x_{k+1}^\tau,\quad \tilde{x}^\tau(t) := x_k^\tau + (t-k\tau)v_{k+1}^\tau,\quad \forall t\in(k\tau,(k+1)\tau]
\end{equation*}
