\begin{definition}
\label{def:global-local-min}
A point $x\in\mathbb{R}^n$ is a \textit{local minimum} (respectively, \textit{global minimum}) of a function $f:\mathbb{R}^n\rightarrow\mathbb{R}$ if $f(x)\leqslant f(y)$ for all $y\in B(x,\epsilon)$ for some $\epsilon>0$ (respectively, $y\in\mathbb{R}^n$). A local minimum is \textit{spurious} if it is not a global minimum.
\end{definition}

From \Cref{def:global-local-min}, one can see the definition of a local minimum only considers the landscape of a function at any finite point. To discuss the function landscape at infinity, we generalize the notion of setwise local minimum first proposed in \cite[Definition 2.5]{joszneurips2018}.

\begin{definition}[Setwise global minimum]\label{def:setwise-global-min}
A subset $S$ of $\mathbb{R}^n$ is a \textit{setwise global minimum} of a function $f:\mathbb{R}^n\rightarrow\mathbb{R}$ if $S$ is a setwise local minimum of $f$ and $\inf_{S} f = \inf_{\mathbb{R}^n} f$. 
\end{definition}

\begin{definition}\label{def:locally-lipschitz}
A function $f:\mathbb{R}^n\rightarrow\mathbb{R}^m$ is \textit{locally Lipschitz} if for all $a \in \mathbb{R}^n$, there exist positive constants $r$ and $L$ such that 
	\begin{equation*}
		\forall\, x,y \in B(a,r), ~~~ \|f(x)-f(y)\| \leqslant L \|x-y\|.
	\end{equation*}
\end{definition}

\begin{definition}
\label{def:Clarke}
\cite[p. 27]{clarke1990} Let $f:\mathbb{R}^n \rightarrow \mathbb{R}$ be a locally Lipschitz function. The \textit{Clarke subdifferential} is the set-valued mapping $\partial f$ from $\mathbb{R}^n$ to the subsets of $\mathbb{R}^n$ defined for all $x \in \mathbb{R}^n$ by
    \begin{equation*}
    \partial f(x) := \{ s \in \mathbb{R}^n ~\vert~ f^\circ(x,d) \geqslant \langle s , d \rangle, ~ \forall\, d\in \mathbb{R}^n \} 
\end{equation*}
where
\begin{equation*}
    f^\circ(x,d) := \limsup_{\tiny\begin{array}{c} y\rightarrow x \\
    t \searrow 0
    \end{array}
    } \frac{f(y+td)-f(y)}{t}.
\end{equation*}
\end{definition}

\begin{definition}
    \label{def:absolute_continuity} 
    \cite[Definition 1 p. 12]{aubin1984differential}
    Given two real numbers $a<b$, a function $x:[a,b]\rightarrow\mathbb{R}^n$ is \textit{absolutely continuous} if for all $\epsilon>0$, there exists $\delta>0$ such that, for any finite collection of disjoint subintervals $[a_1,b_1],\hdots,[a_m,b_m]$ of $[a,b]$ such that $\sum_{i=1}^m b_i-a_i \leqslant \delta$, we have $\sum_{i=1}^m \|x(b_i) - x(a_i)\| \leqslant \epsilon$.
\end{definition}

An absolutely continuous function $x:[0,\infty)\rightarrow\mathbb{R}^n$ is called a \textit{subgradient trajectory} of $f:\mathbb{R}^n\rightarrow\mathbb{R}$ starting at $x_0\in\mathbb{R}^n$ if it satisfies the following differential inclusion with initial condition: 
\begin{equation}\label{eq:ivp-subgrad}
    x'(t) \in -\partial f(x(t)),\quad \text{for almost every $t\geqslant 0$},\quad x(0)=x_0,
\end{equation}
where ``almost every'' means all elements except for those in a set of zero measure.

\begin{definition}\label{def:bdd-subgrad}
A locally Lipschitz lower bounded function $f:\mathbb{R}^n\rightarrow\mathbb{R}$ has \textit{bounded subgradient trajectories} if for any $x_0\in\mathbb{R}^n$, there exists a subgradient trajectory $x$ of $f$ starting at $x_0$ and a constant $r>0$, such that $\|x(t)\|\leqslant r$ for all $t\geqslant 0$. 
\end{definition}

\begin{definition}\label{def:chain-rule}
Let $f:\mathbb{R}^n\rightarrow\mathbb{R}$ be locally Lipschitz. We say $f$ \textit{admits a chain rule} if for any absolutely continuous function $x:[0,\infty)\rightarrow \mathbb{R}^n$, we have
\begin{equation*}
	(f\circ x)'(t) = \langle v, x'(t)\rangle, \quad \forall\, v\in\partial f(x(t)),
\end{equation*}
for almost every $t\in [0,\infty)$. 
\end{definition}

