\section{Proof of \texorpdfstring{\Cref{lem:bdd-const}}{}}\label{app:lem:bdd-const}
Let $S \subset \mathbb{R}^n$ be a setwise local minimum of a continuous function $f:\mathbb{R}^n\rightarrow\mathbb{R}$. Let $U\supset S$ be an open set such that $f(x)\leqslant f(y)$ for all $x \in S$ and $y\in U\setminus S$. Note that $S$ is closed, so its boundary is defined by $\partial S := S\setminus S^\circ$. Let $z\in\partial S$ and consider any real number $\epsilon>0$. Since $f(z)+(-\epsilon,\epsilon)$ is a neighborhood of $f(z)$, by continuity of $f$, there exists a neighborhood $N(z)$ of $z$ such that $f(N(z))\subset f(z)+(-\epsilon,\epsilon)$. Since $U$ is a neighborhood of $z$, $N'(z):=U \cap N(z)$ is also a neighborhood of $z$ with $f(N'(z))\subset f(z)+(-\epsilon,\epsilon)$. The set $N'(z)\cap S$ is nonempty because $z \in S$ and the set $N'(z)\setminus S$ is nonempty because $z\in\partial S$. For any $x \in N'(z) \cap S$ and $y \in N'(z)\setminus S$, it follows that
\begin{equation*}
     \inf_{U \setminus S} f -\epsilon \leqslant f(y)-\epsilon < f(z) < f(x)+\epsilon \leqslant \sup_S f+\epsilon \leqslant \inf_{U\setminus S} f +\epsilon. 
\end{equation*}
The last inequality follows from the definition of setwise local minima. As $\epsilon>0$ was arbitrary, we deduce that 
\begin{equation*}
\label{inf_sup}
    \inf_{U \setminus S} f = f(z) = \sup_S f.
\end{equation*}
Thus, $f$ is a constant on the boundary of $S$ and $f$ attains its maximum over $S$ on the boundary of $S$.

\begin{equation*}
     \inf_{U \setminus S} f -\epsilon \leqslant f(y)-\epsilon < f(z) < f(x)+\epsilon \leqslant \sup_S f+\epsilon \leqslant \inf_{U\setminus S} f +\epsilon. 
\end{equation*}
The last inequality follows from the definition of setwise local minima. As $\epsilon>0$ was arbitrary, we deduce that 
\begin{equation*}
\label{inf_sup}
    \inf_{U \setminus S} f = f(z) = \sup_S f.
\end{equation*}

\begin{proposition}\label{prop:exist}
If $f:\mathbb{R}^n\rightarrow\mathbb{R}$ is locally Lipschitz and bounded below, then there exists a subgradient trajectory of $f$ starting at arbitrary $x_0\in\mathbb{R}^n$. 
\end{proposition}

\begin{proof}
See \Cref{app:prop:exist}. 
\end{proof}

\section{Proof of \texorpdfstring{\Cref{prop:exist}}{}}\label{app:prop:exist}
For a fixed real number $\tau>0$, define a sequence $x_k^\tau$ recurrently by letting $x_0^\tau:=x_0$ and 
\begin{equation*}
    x_{k+1}^\tau \in \arg\min_{x\in\mathbb{R}^n} \left\{f(x)+\frac{\lVert x-x_k^\tau\rVert^2}{2\tau}\right\}, \quad \forall k\in\mathbb{N}. 
\end{equation*}
A solution exists because $f$ is bounded below and the objective function is coercive. Any solution satisfies 
\begin{equation*}
    v_{k+1}^\tau := \frac{x_{k+1}^\tau-x_k^\tau}{\tau} \in -\partial f(x_{k+1}^\tau), \quad \forall k\in\mathbb{N}. 
\end{equation*}
Define two functions $x^\tau,\tilde{x}^\tau:\mathbb{R}_+\rightarrow \mathbb{R}^n$ where $\mathbb{R}_+:=[0,\infty)$ by
\begin{equation*}
    x^\tau(t) := x_{k+1}^\tau,\quad \tilde{x}^\tau(t) := x_k^\tau + (t-k\tau)v_{k+1}^\tau,\quad \forall t\in(k\tau,(k+1)\tau]
\end{equation*}
for all $k\in\mathbb{N}$, with initial condition $x^\tau(0)=\tilde{x}^\tau(0)=x_0$. Note that $\tilde{x}^\tau$ is absolutely continuous because it is piecewise affine. On the contrary, $x^\tau$ is not continuous. Also, define $v^{\tau}:\mathbb{R}_+\rightarrow\mathbb{R}^n$ by 
\begin{equation*}
    v^\tau(t) := v_{k+1}^\tau, \quad \forall t\in(k\tau,(k+1)\tau],\quad \forall k\in\mathbb{N}, 
\end{equation*}
and choose $v^\tau(0)\in -\partial f(x_0)$. Since  $(\tilde{x}^\tau)'=v^\tau$ on $(k\tau,(k+1)\tau)$ for all $k \in \mathbb{N}$, and $v^\tau(t)\in -\partial f(x^\tau(t))$ for all $t\geqslant 0$, we conclude that $(\tilde{x}^\tau)'(t)\in -\partial f(x^\tau(t))$ for almost every $t\in\mathbb{R}_+$. By optimality of $x_{k+1}^\tau$, we have 
\begin{equation*}
    f(x_{k+1}^\tau) + \frac{\lVert x_{k+1}^\tau-x_k^\tau\rVert^2}{2\tau} \leqslant f(x_k^\tau), \quad \forall k\in\mathbb{N}. 
\end{equation*}
For any $l\in\mathbb{N}$, we have 
\begin{equation*}
    \sum_{k=0}^l\frac{\lVert x_{k+1}^\tau-x_k^\tau\rVert^2}{2\tau} \leqslant f(x_0^\tau) - f(x_{l+1}^\tau) \leqslant f(x_0) - \inf_{\mathbb{R}^n} f =: C < \infty
\end{equation*}
since $f$ is bounded below. Observe that 
\begin{equation*}
    \sum_{k=0}^l\frac{\lVert x_{k+1}^\tau-x_k^\tau\rVert^2}{2\tau} = \sum_{k=0}^l\frac{\tau}{2}\lVert v_{k+1}^\tau\rVert^2 = \frac{1}{2}\sum_{k=0}^l\int_{k\tau}^{(k+1)\tau}\left\lVert (\tilde{x}^\tau)'(t)\right\rVert^2dt. 
\end{equation*}
Fix $T \geqslant 0$ from now on. From the above, we have
\begin{equation}\label{eq:L2-bounded}
    \int_0^T\left\lVert (\tilde{x}^\tau)'(t)\right\rVert^2dt \leqslant \sum_{k=0}^{\lfloor T/\tau\rfloor}\int_{k\tau}^{(k+1)\tau}\left\lVert (\tilde{x}^\tau)'(t)\right\rVert^2dt \leqslant 2C. 
\end{equation}
Since $\tilde{x}^\tau$ is absolutely continuous, for any $s,t\in [0,T]$ we have
\begin{subequations}\label{eq:1/2-holder}
    \begin{align}
    \|\tilde{x}^\tau(t)-\tilde{x}^\tau(s)\| &= \left\|\int_s^t(\tilde{x}^\tau)'(u)\;du\right\| \\
    &\leqslant \left(\int_0^T\left\lVert (\tilde{x}^\tau)'(t)\right\rVert^2dt\right)^{1/2}\vert t-s\vert^{1/2} \leqslant \sqrt{2C}\vert t-s\vert^{1/2} \label{eq:1/2-holder_cs} 
\end{align}
\end{subequations}
where we use the Cauchy-Schwarz inequality. Now one can see $(\tilde{x}^\tau)_{\tau>0}$ is a family of uniformly bounded and equicontinuous functions on the compact interval $[0,T]$. Therefore, by Arzel\`a-Ascoli theorem \cite[Theorem 7.25]{rudin1964principles}, there exists a sequence of positive reals $(\tau_k)_{k\in\mathbb{N}}$ such that $\tau_k\to 0$ and $\tilde{x}^{\tau_k}\to x^*$ uniformly on $[0,T]$ as $k\to\infty$. For all $k\in \mathbb{N}$ and $t\in (k\tau,(k+1)\tau]$, we have $\tilde{x}^\tau((k+1)\tau)=x_k^\tau + \tau v^\tau_{k+1} = x^\tau_{k+1} = x^\tau(t)$. Thus $\|\tilde{x}^\tau(t)-x^\tau(t)\| = \|\tilde{x}^\tau(t)-\tilde{x}^\tau((k+1)\tau)\| \leqslant \sqrt{2C}\tau^{1/2}$ for all $t\in [0,T]$ where the inequality is due to \Cref{eq:1/2-holder} (take $s:=(k+1)\tau$).
Combined with the fact that $\tilde{x}^{\tau_k}\to x^*$ uniformly on $[0,T]$, one can see that $x^{\tau_k}\to x^*$ uniformly on $[0,T]$. Since \cref{eq:L2-bounded} implies that $((\tilde{x}^{\tau_k})')_{k\in\mathbb{N}}$ is a bounded sequence in $L^2([0,T],\mathbb{R}^n)$, there exists a subsequence $(\tau_{k_j})_{j\in\mathbb{N}}$ such that $(\tilde{x}^{\tau_{k_j}})'\to v^*$ weakly in $L^1([0,T],\mathbb{R}^n)$ as $j\to\infty$ by \cite[Corollary 14 p. 413]{Fitzpatrick2010}. Since $\tilde{x}^{\tau_{k_j}}$ is absolutely continuous, for all $t\in[0,T]$, we have 
\begin{equation*}
    \tilde{x}^{\tau_{k_j}}(t) - \tilde{x}^{\tau_{k_j}}(0) = \int_0^t(\tilde{x}^{\tau_{k_j}})'(u)\;du. 
\end{equation*}
Take $j\to\infty$ on both sides, we have 
\begin{equation*}
    x^*(t) - x^*(0) = \int_0^tv^*(u)\;du, 
\end{equation*}
where the convergence of the integral relies on the fact that the constant functions equal to the canonical basis of $\mathbb{R}^n$ lie in $L^\infty([0,T],\mathbb{R}^n)$. Thus, $x^*$ is absolutely continuous and $(x^*)'(t)=v^*(t)$ for almost every $t\in[0,T]$. Recall that for all $k\in \mathbb{N}$, it holds for almost every $t\in[0,T]$ that
\begin{equation*}
    (\tilde{x}^{\tau_k})'(t) = v^{\tau_k}(t) \in -\partial f(x^{\tau_k}(t)). 
\end{equation*}
Since $f$ is locally Lipschitz, the set-valued function $-\partial f$ is upper semicontinuous \cite[2.1.5 Proposition (d) p. 29]{clarke1990} with nonempty compact values \cite[2.1.2 Proposition (a) p. 27]{clarke1990}, hence proper upper hemicontinuous \cite[Proposition 1 p. 60]{aubin1984differential}. In addition, $x^{\tau_k}\to x^*$ uniformly on $[0,T]$ and $(\tilde{x}^{\tau_k})'\to (x^*)'$ weakly in $L^1([0,T],\mathbb{R}^n)$. Therefore,  $(x^*)'(t)\in-\partial f(x^*(t))$ for almost all $t\in[0,T]$ by \cite[Theorem 1 p. 60]{aubin1984differential}\footnote{In the theorem we take $F:=-\partial f$, $X=Y:=\mathbb{R}^n$, and $I:=[0,T]$.}. The initial condition also holds since $\tilde{x}^{\tau}(0)=x_0$ for all $\tau>0$. 
\vskip 1ex
We have proved that for any initial point $x_0$, there exists $x^*:[0,T]\rightarrow\mathbb{R}^n$ such that $(x^*)'(t)=-\partial f(x^*(t))$ holds for almost every $t\in [0,T]$ with any $T>0$. Since $T$ is independent of $x_0$, by setting $T=1$, there exists a sequence of absolutely continuous functions $(x_k)_{k\in\mathbb{N}}$ such that 
\begin{equation*}
    x_k'(t)\in -\partial f(x_k(t)), \quad \mathrm{for~a.e.}~t \in [0,1], \quad x_k(0) = x_{k-1}(1), 
\end{equation*}
for all $k\in\mathbb{N}$ where $x_{-1}(0)=x_0$. Therefore, the desired function $x:[0,\infty)\rightarrow \mathbb{R}^n$ can be defined in a piecewise fashion by 
\begin{equation*}
    x(t) := x_k(t-k),\quad t\in[k,k+1),\quad \forall k\in\mathbb{N}. 
\end{equation*}
By construction, $x$ is absolutely continuous on any compact interval $[a,b]\subset[0,\infty)$.

